import{_ as s,a0 as o,w as l,s as p,ao as u,I as a,x as i,a1 as n,A as r}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const x=JSON.parse('{"title":"如何在 Ubuntu 16.10 的 Unity 8 上运行老式 Xorg 程序 | LCTT x X-CMD","titleTemplate":false,"description":"如何在 Ubuntu 16.10 的 Unity 8 上运行老式 Xorg 程序 | LCTT (201701) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"如何在 Ubuntu 16.10 的 Unity 8 上运行老式 Xorg 程序 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"如何在 Ubuntu 16.10 的 Unity 8 上运行老式 Xorg 程序 | LCTT (201701) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201701/20161024 How to Use Old Xorg Apps in Unity 8 on Ubuntu 16.10","title":"如何在 Ubuntu 16.10 的 Unity 8 上运行老式 Xorg 程序","tag":"201701","desc":""},"relativePath":"201701/20161024 How to Use Old Xorg Apps in Unity 8 on Ubuntu 16.10.md","filePath":"[post].md"}'),d={name:"201701/20161024 How to Use Old Xorg Apps in Unity 8 on Ubuntu 16.10.md"};function b(g,t,y,m,h,U){const e=o("Link");return l(),p("div",null,[t[13]||(t[13]=u('<h1 id="如何在-ubuntu-16-10-的-unity-8-上运行老式-xorg-程序" tabindex="-1">如何在 Ubuntu 16.10 的 Unity 8 上运行老式 Xorg 程序 <a class="header-anchor" href="#如何在-ubuntu-16-10-的-unity-8-上运行老式-xorg-程序" aria-label="Permalink to “如何在 Ubuntu 16.10 的 Unity 8 上运行老式 Xorg 程序”">​</a></h1><p><img src="https://maketecheasier-2d0f.kxcdn.com/assets/uploads/2016/10/unity8-feature-image.jpg" alt="" title="How to Use Old Xorg Apps in Unity 8 on Ubuntu 16.10s"></p><p>随着 Ubuntu 16.10 的发布，Unity 8 越来越吸引到了更多人的关注。这是因为在这个大家最爱的 Linux 发行版的最新版本中可以体验其带有的试验性桌面。桌面发行版是人们最熟悉的 Unity 环境，但有一点点不同。它不再使用 X11 图形技术，Ubuntu 的开发者选择了另一种截然不同的方式。</p><p>原来，Unity 8 用的是 Mir，这是 Ubuntu 为了在 Linux 上提供显示服务而做出的努力。这项技术已经在 Ubuntu phone 和平板上大量使用，但是这次新版是我们在桌面环境上第一次见到 Mir 。</p><p>这项技术相当新颖，结果是没多少 Linux 程序能运行在它之上。不是所有，那也是大部分的程序设计在 Xorg 和 X11 之上运行。如果你想要试试在 Unity 8 上运行这些程序，你肯定会为在 Unity 8上确实能够运行之前的 Xorg 程序而高兴。接下来是如何做！</p><h3 id="登录进-unity-8" tabindex="-1">登录进 Unity 8 <a class="header-anchor" href="#登录进-unity-8" aria-label="Permalink to “登录进 Unity 8”">​</a></h3><p><img src="https://maketecheasier-2d0f.kxcdn.com/assets/uploads/2016/10/unity8-select-unity-8-login.jpg" alt="unity8-select-unity-8-login" title="unity8-select-unity-8-login"></p><p>Unity 8 在 Ubuntu 16.10 上是一个可选会话。在使用之前只须牢记一件事情：它不会加载 AMD 的图形驱动，Intel 的同样不会加载。唯一支持的图形驱动是 Nvidia 的开源驱动。要用 Unity 8 的话，只要像往常那样启动 Ubuntu，然后，在登录进去之前，点击用户名上面的 Ubuntu 图标，选择 Unity8 选项。如果万事顺利的话，这个新的、试验性的桌面环境将会加载。</p><p><strong>注意</strong>： Unity 8 非常新而且不稳定，自行承担使用风险。</p><h3 id="安装-libertine" tabindex="-1">安装 Libertine <a class="header-anchor" href="#安装-libertine" aria-label="Permalink to “安装 Libertine”">​</a></h3><p>Xorg 程序（例如 Firefox 等）确实能在 Unity 8 上使用，在使用之前需要一点小调整。在 Mir 桌面上用终端打开 Libertine ，在 Scopes 窗口中点击终端图标就能完成。一旦打开，输入你的密码。接下来，输入以下的命令：</p><p><img src="https://maketecheasier-2d0f.kxcdn.com/assets/uploads/2016/10/unity8-installing-libertine-in-terminal.jpg" alt="unity8-installing-libertine-in-terminal" title="unity8-installing-libertine-in-terminal"></p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sudo apt install libertine-tools libertine-scope libertine</span></span></code></pre></div><p>当这些程序完成安装后，点击并拖动 Scopes 窗口以刷新内容。然后，在面板上点击来启动 libertine。</p><h3 id="新建-xorg-容器" tabindex="-1">新建 Xorg 容器 <a class="header-anchor" href="#新建-xorg-容器" aria-label="Permalink to “新建 Xorg 容器”">​</a></h3><p>打开 Libertine，就可以新建一些（应用）容器了。这些容器很特别，因为它们能让基于 X11 的 Linux 程序在 Mir/Unity 8 桌面上的容器之中运行。另外，如果需要支持 32 位应用，勾选“i386 multiarch support”复选框。否则，什么都不要动（或者输入名字和密码），点击“OK”。</p><p><img src="https://maketecheasier-2d0f.kxcdn.com/assets/uploads/2016/10/unity8-libertine-create-new-container.jpg" alt="unity8-libertine-create-new-container" title="unity8-libertine-create-new-container"></p><p>在这之后，这个 Xorg 容器就准备好，可以使用了。在 Libertine 找到它并启动。删除也很容易，右键点击容器，选择“删除”选项。</p><p><strong>注意</strong>：每一个 Xorg 容器有 500 MB的最大内存限制。所以多个容器是有必要的。</p><h3 id="安装软件" tabindex="-1">安装软件 <a class="header-anchor" href="#安装软件" aria-label="Permalink to “安装软件”">​</a></h3><p><img src="https://maketecheasier-2d0f.kxcdn.com/assets/uploads/2016/10/unity8-libertine-install-software.jpg" alt="unity8-libertine-install-software" title="unity8-libertine-install-software"></p><p>在 Libertine 容器中安装软件有两个方法。第一种是允许用户启动容器后选择“输入包名或者 Debian 文件”，这意味着用户可以在软件中心或者终端找到一个软件的名字，然后在 Libertine 中输入它来安装。也可以指定特定的 DEB 文件来安装，可以在Libertine LXC 容器中直接搜索安装包。</p><p><strong>注意</strong>：Unity 8 非常新，一些程序或许不能在 Libertine 里加载或者完全安装。</p><h3 id="结论" tabindex="-1">结论 <a class="header-anchor" href="#结论" aria-label="Permalink to “结论”">​</a></h3><p>Unity 8 展现了不少的新特性，它现代、时髦，而且比之前任何一个 Unity 迭代版本都快。唯一限制它的就是使用率。事实是大部分用户更乐意选择实用的应用程序，而不是一个别致新颖的桌面环境。某种程度上来说，使用 Libertine 能解决这个问题，但它不会永久有效。早晚有一天，Canonical 都需要自行移植这些程序或者向社区求助来彻底解决这个问题。</p><hr>',26)),a("p",null,[t[1]||(t[1]=i("via: ",-1)),n(e,{href:"https://www.maketecheasier.com/use-old-xorg-apps-unity-8/"},{default:r(()=>[...t[0]||(t[0]=[i("https://www.maketecheasier.com/use-old-xorg-apps-unity-8/",-1)])]),_:1})]),a("p",null,[t[5]||(t[5]=i("作者：",-1)),n(e,{href:"https://www.maketecheasier.com/author/derrikdiener/"},{default:r(()=>[...t[2]||(t[2]=[i("Derrik Diener",-1)])]),_:1}),t[6]||(t[6]=i(" 译者：",-1)),n(e,{href:"https://github.com/ypingcn"},{default:r(()=>[...t[3]||(t[3]=[i("ypingcn",-1)])]),_:1}),t[7]||(t[7]=i(" 校对：",-1)),n(e,{href:"https://github.com/wxy"},{default:r(()=>[...t[4]||(t[4]=[i("wxy",-1)])]),_:1})]),a("p",null,[t[10]||(t[10]=i("本文由 ",-1)),n(e,{href:"https://github.com/LCTT/TranslateProject"},{default:r(()=>[...t[8]||(t[8]=[i("LCTT",-1)])]),_:1}),t[11]||(t[11]=i(" 组织编译，",-1)),n(e,{href:"https://linux.cn/"},{default:r(()=>[...t[9]||(t[9]=[i("Linux中国",-1)])]),_:1}),t[12]||(t[12]=i(" 荣誉推出",-1))])])}const k=s(d,[["render",b]]);export{x as __pageData,k as default};
